[3861] = { en = "CLUCK!", tier = 1,
  t = "TOK!",
  d = "\"Tok... tok... tok... KAKAAK!$B$BTok... tok... tok.\"$B$BDe kip kijkt naar je op. Dan begint ze met haar klauwen in de grond te krabben. Je denkt dat ze een woord spelt, maar je weet niet zeker welk woord. Is het misschien... S-A-L-D-E-A-N? Voordat je iets kunt vragen, draait de kip zich om. Ze gaat weer verder met haar eigen dingen.",
  o = "Zoek wat Special Chicken Feed en ga terug naar je bevriende kip. Als je het hebt gevonden, doe dan eerst /cheer naar de kip. Probeer haar daarna het Special Chicken Feed te geven.",
  p = "De kip staart je aan met donkere, koude ogen. Ze wacht hongerig op je.$B$B\"KAKAAAAK!$B$BTok... tok... tok.\"",
  c = "\"KAKAAK!!!\"$B$BDe kip begint het voer dat je hebt neergelegd op te schrokken.$B$BNa een moment kijkt de kip geschrokken om zich heen. Ze schuifelt ongemakkelijk heen en weer. Is deze kip zwanger? Je kunt beter even onder haar kijken.",
  g = { {"klauwen", "claws (klauw)"}, {"krabben", "to scratch"}, {"spelt", "spells (spellen)"}, {"bevriende", "befriended"}, {"staart", "stares (staren)"}, {"hongerig", "hungrily"}, {"voer", "feed"}, {"op te schrokken", "to gobble up (opschrokken)"}, {"geschrokken", "startled"}, {"schuifelt", "shuffles (schuifelen)"}, {"ongemakkelijk", "uncomfortably"}, {"zwanger", "pregnant"} },
},

[5805] = { en = "Welcome!", tier = 1,
  t = "Welkom!",
  d = "Welkom in World of Warcraft!$B$BAls speciaal bedankje omdat je de World of Warcraft Collector's Edition hebt gekocht: lever deze cadeaubon in bij Merissa Stilwell in Northshire Valley. Je krijgt dan een cadeau: een klein maatje dat met je meegaat op je zoektocht naar avontuur en roem.$B$BNogmaals bedankt, en geniet van je verblijf in World of Warcraft!$b",
  o = "Breng de Northshire Gift Voucher naar Merissa Stilwell.",
  p = "Gegroet! Leuk om je te ontmoeten!$B$BIk zie dat je een speciale bon hebt. Geef hem aan mij, dan bied ik je er iets voor in ruil.",
  c = "Jij bent echt een bijzondere held, $N. We heten je welkom in de wereld van Azeroth en bieden je een van deze unieke cadeaus aan!",
  g = { {"bedankje", "thank-you, token of thanks"}, {"lever ... in", "hand in (inleveren)"}, {"cadeaubon", "gift voucher"}, {"maatje", "buddy, companion"}, {"zoektocht", "quest, search"}, {"roem", "glory, fame"}, {"verblijf", "stay"}, {"gegroet", "greetings"}, {"in ruil", "in exchange"}, {"heten je welkom", "welcome you (welkom heten)"} },
},

