[830] = { en = "The Admiral's Orders", tier = 1,
  t = "De bevelen van de admiraal",
  d = "Je maakt de oude, verweerde envelop open en vindt een officieel uitziend document. Je herkent het zegel van Admiral Proudmoore.$b$bDit ziet er belangrijk uit. Misschien wil Gar'Thok, de commandant van Razor Hill, deze informatie graag hebben.",
