[9265] = { en = "Investigate the Scourge of the Undercity", tier = 1,
  t = "Onderzoek de Scourge bij Undercity",
  d = "De Scourge heeft zijn kamp vlak voor onze deur opgeslagen. We kunnen niet stil blijven zitten! Je helpt toch zeker mee om Undercity te verdedigen tegen deze vervloekte indringers?$b$bBuiten zijn vreemde cirkels met runen. Ze gloeien met dezelfde energie die om de ondoden en de Necropolis hierboven hangt. Ze betekenen iets, dat weet ik zeker. En ik wil dat jij uitzoekt wat. Maak ondertussen hun aantal kleiner. Breng me bewijs dat die monsters dood zijn, samen met wat je hebt ontdekt. Dan krijg je een beloning. Ga!",
  o = "Verzamel drie Dim Necrotic Stones van de Scourge buiten Undercity en onderzoek de gloeiende cirkels met runen bij hun kamp.",
  p = "Heb je de invasie al onderzocht? We hebben geen tijd om te treuzelen!",
  c = "Hmm. Uit wat je me vertelt... de stemmen in de cirkels worden vast gebruikt voor een soort communicatie. Ik huiver als ik eraan denk met welke onnatuurlijke geesten je via zulke magie contact maakt. Hoe dan ook, je bent heel en gezond van geest teruggekomen. De Argent Dawn is je dankbaar voor je hulp.",
  e = "Onderzoek een cirkel",
  g = { {"vervloekte", "accursed (vervloekt)"}, {"indringers", "invaders (indringer)"}, {"runen", "runes (rune)"}, {"gloeien", "to glow"}, {"ondoden", "the undead"}, {"uitzoekt", "find out (uitzoeken)"}, {"bewijs", "proof"}, {"treuzelen", "to dawdle"}, {"huiver", "shudder (huiveren)"}, {"onnatuurlijke", "unnatural"}, {"gezond van geest", "sane, of sound mind"} },
},

[834] = { en = "Winds in the Desert", tier = 1,
  t = "Winden in de woestijn",
  d = "Ik ben Rezlak, een van Gazlowes jongens. De baas heeft me gestuurd om de orks hier in Durotar te helpen. Alles ging goed, behalve met de karavanen. Ik krijg ze maar niet veilig! Dat maakt mijn werk wat moeilijker, snap je?$b$bDe laatste lading... ze beloofden dat die erdoor zou komen!... is gestolen door de Dustwind-harpijen van... waar was het ook alweer... Razorwind Canyon?$b$bIk moet die voorraden hebben, anders krijg ik nooit iets gedaan! Volg de grote kloof naar het zuiden. Daar vind je het ravijn. Het is recht in de west- en oostwanden uitgesneden.",
  o = "Haal 5 Sacks of Supplies terug en breng ze naar Rezlak bij Orgrimmar.",
  p = "Ik ben goed in mijn werk, begrijp me niet verkeerd, maar dit is belachelijk! Wat moet ik doen, zandkastelen bouwen?",
  c = "Hé, dat is precies wat ik nodig had! Je hebt onze voorraden terug. Geweldig. Ik kan weer aan het werk zodra ik iemand vind die deze zakken voor me kan sjouwen.",
  g = { {"orks", "orcs (ork)"}, {"karavanen", "caravans (karavaan)"}, {"lading", "shipment, load"}, {"harpijen", "harpies (harpij)"}, {"kloof", "canyon, gorge"}, {"ravijn", "ravine"}, {"wanden", "walls (wand)"}, {"uitgesneden", "cut out (uitsnijden)"}, {"belachelijk", "ridiculous"}, {"zandkastelen", "sand castles (zandkasteel)"}, {"sjouwen", "to haul, lug"} },
},

[6722] = { en = "The Hunter's Path", tier = 1,
  t = "Het pad van de jager",
  d = "Hallo, jonge jager. Je ziet eruit alsof je goed genoeg bent om met een beest om te gaan en het te trainen als je maatje.$B$BJe moet naar Dazalar in Dolanaar gaan. Hij kan je op het pad zetten om zelf een huisdier te verdienen.",
  o = "Spreek met Dazalar in Dolanaar.",
  c = "Ja, het is tijd om je te trainen...",
  g = { {"pad", "path"}, {"jager", "hunter"}, {"ziet eruit", "look (eruitzien)"}, {"om te gaan", "to handle (omgaan met)"}, {"beest", "beast"}, {"maatje", "buddy, companion"}, {"verdienen", "to earn"} },
},

