[835] = { en = "Securing the Lines", tier = 1,
  t = "De lijnen veiligstellen",
  d = "Gazlowe zei ooit tegen me: \"Rezlak. Er is één ding dat je moet weten in het leven. Als je wilt dat iets goed gebeurt, moet je het zelf doen.\"$b$bIk kan het niet hebben dat we al onze karavanen kwijtraken. Dus ik ga het zelf oplossen. Drygulch Ravine ligt in het oostelijke deel van Razorwind Canyon. Als we alle harpijen daar doden, zijn de routes veilig.$b$bNatuurlijk heeft Gazlowe me nog één ding geleerd: \"Voor een prijs krijg je alles gedaan.\" Dus, help je me, $n?",
  o = "Dood 12 Dustwind Savages en 8 Dustwind Storm Witches voor Rezlak bij Drygulch Ravine.",
  p = "Dat zou je niet denken van iemand als mijn baas Gazlowe, maar hij leek altijd te weten hoe het zat. \"Wees niet bang om die grote stap te zetten,\" zei hij.$B$BAls we niets doen, blijven de harpijen ons lastigvallen. En dan blijven de karavanen aangevallen worden, hè?",
  c = "Ik denk dat ik nu weer rustig kan ademhalen. Ik weet nu dat de harpijen onze karavanen met voorraden niet meer lastigvallen. En geen moment te vroeg! Ik hoor dat er met de volgende lading leuk klein speelgoed voor me komt!$B$BJe bent best goed in wat je doet, $N. Je zou mijn baas in Ratchet eens moeten opzoeken. Ik wed dat hij wel werk voor je heeft.$B$BO, en maak je geen zorgen. Ik vergeet niet om je te betalen voor je hulp.",
  g = { {"veiligstellen", "to secure"}, {"kwijtraken", "to lose"}, {"oplossen", "to solve, sort out"}, {"oostelijke", "eastern (oostelijk)"}, {"hoe het zat", "how things were, the score"}, {"lastigvallen", "to bother, harass"}, {"ademhalen", "to breathe"}, {"geen moment te vroeg", "not a moment too soon"}, {"speelgoed", "toys"}, {"opzoeken", "to look up, track down"}, {"wed", "bet (wedden)"} },
},

[832] = { en = "Burning Shadows", tier = 1,
  t = "Brandende schaduwen",
  d = "<Woorden komen uit de hanger en gaan je hoofd in.>$B$BGazz'uz?$B$BGazz'uz... breng verslag uit!$B$BWe horen dat je bent ontdekt in Skull Rock. Je moet je voorbereiden op een aanval!$B$BGazz'uz, ik beveel je te spreken! Spreek, of ik zorg ervoor dat Neeru Fireblade weet dat je er bent. Dan valt hij je snel en wreed aan.$B$BTest je vaardigheden niet tegen Neeru...$B$B... Gazz'uz, ben je daar...?",
  o = "Breng dit oog naar Neeru Fireblade.",
  p = "Je hebt iets belangrijks te melden. Ik voel het achter je ogen.",
  c = "<Bekijkt de Eye of Burning Shadow>$b$bInteressant. Noemde de stem die je hoorde mijn naam? Ik sta erom bekend dat ik op vijanden van onze Warchief jaag, maar... het is vreemd dat juist ik genoemd werd. Je hebt deze hanger afgepakt van de sekteleden van de Burning Blade. Nog vreemder is dat hun naam zo veel op die van mij lijkt.$b$bIk moet deze hanger bestuderen. Ik moet hem bestuderen en goed nadenken over wat het bericht betekent.$b$bDank je dat je dit naar mij hebt gebracht, $N. Je hebt je volk een grote dienst bewezen.",
  g = { {"hanger", "pendant"}, {"breng verslag uit", "report (verslag uitbrengen)"}, {"ontdekt", "discovered (ontdekken)"}, {"voorbereiden", "to prepare"}, {"beveel", "order, command (bevelen)"}, {"wreed", "brutal, cruel"}, {"vaardigheden", "skills (vaardigheid)"}, {"melden", "to report"}, {"sta erom bekend", "am known for (bekendstaan)"}, {"afgepakt", "taken away (afpakken)"}, {"sekteleden", "cultists (sektelid)"}, {"bestuderen", "to study"}, {"een dienst bewezen", "did a service (een dienst bewijzen)"} },
},

[926] = { en = "Flawed Power Stone", tier = 1,
  t = "Gebrekkige krachtsteen",
  c = "Deze stenen zitten vol magische energie, maar ze hebben expres een fout. Ze zijn erg instabiel. Als je ze van de tafel haalt, verbruiken ze zichzelf snel.",
  g = { {"gebrekkige", "flawed (gebrekkig)"}, {"krachtsteen", "power stone"}, {"expres", "on purpose"}, {"fout", "flaw, mistake"}, {"instabiel", "unstable"}, {"verbruiken", "consume, use up"} },
},

[8846] = { en = "Five Signets for War Supplies", tier = 1,
  t = "Vijf zegels voor oorlogsvoorraden",
  o = "Goed, dan is het geregeld. Hier zijn je voorraden, $c. Wil je nog een keer ruilen? Dan geef ik daar toestemming voor. Zeg het maar, dan regel ik het.$B$BGa zo door, $N. We hebben al het oorlogsmateriaal nodig dat we bij elkaar kunnen krijgen, als we dit willen winnen. Als we allemaal ons deel doen, dan is de overwinning van ons!",
  p = "Ah, je komt voor extra voorraden voor jezelf, hè? Nou, ik begrijp best dat je meer materiaal nodig hebt... kijk maar om je heen als je bewijs wilt.$B$BIk geef je wat extra voorraden. Maar je moet me daarvoor wel genoeg erezegels geven. Je krijgt geen erkenning als je de zegels zo inlevert. Maar misschien vind je iets nuttigs dat je in leven houdt als de strijd eindelijk begint.",
  c = "Goed, dan is het geregeld. Hier zijn je voorraden, $c. Wil je nog een keer ruilen? Dan geef ik daar toestemming voor. Zeg het maar, dan regel ik het.$B$BGa zo door, $N. We hebben al het oorlogsmateriaal nodig dat we bij elkaar kunnen krijgen, als we dit willen winnen. Als we allemaal ons deel doen, dan is de overwinning van ons!",
  g = { {"geregeld", "settled, arranged (regelen)"}, {"voorraden", "supplies (voorraad)"}, {"ruilen", "to exchange, trade"}, {"toestemming", "permission, authorization"}, {"oorlogsmateriaal", "war materiel"}, {"overwinning", "victory"}, {"erezegels", "commendation signets (erezegel)"}, {"erkenning", "recognition"}, {"inlevert", "hand in (inleveren)"}, {"strijd", "battle"} },
},

[1782] = { en = "Furen's Armor", tier = 2,
  t = "Het pantser van Furen",
  c = "Hier is je pantser, $N. Dit houdt de zwaarste aanvallen tegen, of ik heet geen Furen Longbeard!$B$BEn ik moet jou bedanken. Ik heb veel geleerd toen ik werkte met de materialen die je me bracht. Ik denk dat ik ooit nog eens een doorbraak heb!$B$BIk ga wat ik heb geleerd naar andere smeden van de Alliance sturen.$B$BIk zal ze vertellen dat je een grote hulp was. Misschien willen ze dan ook iets voor jou terugdoen.",
  g = { {"pantser", "armor"}, {"houdt ... tegen", "stands up to, stops (tegenhouden)"}, {"zwaarste", "strongest, heaviest (zwaar)"}, {"aanvallen", "assaults, attacks (aanval)"}, {"materialen", "materials (materiaal)"}, {"doorbraak", "breakthrough"}, {"smeden", "blacksmiths (smid)"}, {"terugdoen", "to do something in return"} },
},

[8847] = { en = "Ten Signets for War Supplies", tier = 2,
  t = "Tien zegels voor oorlogsvoorraden",
  o = "Goed, dan is het geregeld: hier zijn je voorraden, $c. Wil je nog eens ruilen, dan ben ik bereid om daar toestemming voor te geven. Zeg het maar en ik zorg ervoor.$B$BGa zo door, $N. We hebben al het oorlogsmateriaal nodig dat we bij elkaar kunnen krijgen als we dit willen winnen. Als iedereen zijn deel doet, ligt de overwinning voor het grijpen!",
  p = "Ah, je komt hier voor extra voorraden voor jezelf, hè? Nou, ik begrijp best dat er meer materiaal nodig is... kijk maar eens om je heen als je bewijs wilt.$B$BIk geef je wat extra voorraden, maar daarvoor moet je me wel het juiste aantal erezegels geven. Je krijgt geen erkenning als je de zegels op deze manier inlevert. Toch vind je misschien iets nuttigs dat je in leven houdt wanneer de strijd eindelijk losbarst.",
  c = "Goed, dan is het geregeld: hier zijn je voorraden, $c. Wil je nog eens ruilen, dan ben ik bereid om daar toestemming voor te geven. Zeg het maar en ik zorg ervoor.$B$BGa zo door, $N. We hebben al het oorlogsmateriaal nodig dat we bij elkaar kunnen krijgen als we dit willen winnen. Als iedereen zijn deel doet, ligt de overwinning voor het grijpen!",
  g = { {"geregeld", "settled, arranged (regelen)"}, {"voorraden", "supplies (voorraad)"}, {"bereid", "prepared, willing"}, {"toestemming", "permission, authorization"}, {"oorlogsmateriaal", "war materiel"}, {"ligt de overwinning voor het grijpen", "victory is ours for the taking"}, {"erezegels", "commendation signets (erezegel)"}, {"erkenning", "recognition"}, {"inlevert", "hand in (inleveren)"}, {"losbarst", "breaks out (losbarsten)"} },
},

[8848] = { en = "Fifteen Signets for War Supplies", tier = 3,
  t = "Vijftien zegels voor oorlogsvoorraden",
